'use client';

import { Bot, Check, ChevronRight } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Collapsible, CollapsiblePanel, CollapsibleTrigger } from '@/components/ui/collapsible';
import { iconEnterClass, MarkTile } from '@/components/ui/ai/mark-tile';

type AgentDraftTool = {
	id: string;
	label: string;
	icon?: React.ReactNode;
};

type AgentDraftAction = {
	id: string;
	label: React.ReactNode;
	/** Label shown in the settled chip once this action is chosen. */
	chosenLabel?: React.ReactNode;
	variant?: 'default' | 'outline';
};

type AgentDraftCardProps = Omit<React.ComponentProps<'div'>, 'children'> & {
	name: React.ReactNode;
	badge?: React.ReactNode;
	schedule?: React.ReactNode;
	tools?: AgentDraftTool[];
	steps?: React.ReactNode[];
	actions?: AgentDraftAction[];
	/** Settled action id; replaces the action row with a summary chip. */
	chosenActionId?: string;
	onAction?: (actionId: string) => void;
	defaultOpen?: boolean;
};

/**
 * Proposed agent spec an assistant drafts in chat: schedule, tools, and the
 * ordered steps it will run. Nothing runs until the host handles an action.
 */
function AgentDraftCard({
	name,
	badge = 'Draft',
	schedule,
	tools = [],
	steps = [],
	actions = [],
	chosenActionId,
	onAction,
	defaultOpen = true,
	className,
	...props
}: AgentDraftCardProps) {
	const chosen = actions.find((action) => action.id === chosenActionId);

	return (
		<div
			data-slot="agent-draft-card"
			className={cn('animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] overflow-hidden rounded-xl bg-card shadow-card motion-reduce:animate-none', className)}
			{...props}
		>
			<Collapsible defaultOpen={defaultOpen}>
				<div className="flex h-10 items-center gap-2 px-2">
					<CollapsibleTrigger className="group flex min-w-0 flex-1 cursor-pointer items-center justify-start gap-2 rounded-md font-normal py-1 text-start outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
						<ChevronRight
							aria-hidden="true"
							className="size-3.5 shrink-0 text-muted-foreground transition-transform duration-(--duration-moderate) ease-out group-data-panel-open:rotate-90 motion-reduce:transition-none rtl:-scale-x-100 rtl:group-data-panel-open:scale-x-100"
						/>
						<MarkTile className="size-5 [&_svg:not([class*=size-])]:size-3">
							<Bot />
						</MarkTile>
						<span title={typeof name === 'string' ? name : undefined} className="truncate font-mono text-[0.8125rem] text-foreground">
							{name}
						</span>
					</CollapsibleTrigger>
					{badge ? (
						<span className="inline-flex h-5 shrink-0 items-center rounded-[5px] border border-border px-1.5 text-xs text-muted-foreground">
							{badge}
						</span>
					) : null}
				</div>
				<CollapsiblePanel>
					{schedule || tools.length ? (
						<dl className="grid grid-cols-[5.5rem_minmax(0,1fr)] gap-x-3 gap-y-2 border-t border-border px-4 py-3 text-[0.8125rem]">
							{schedule ? (
								<>
									<dt className="text-muted-foreground">Runs</dt>
									<dd className="min-w-0 text-foreground [overflow-wrap:anywhere]">{schedule}</dd>
								</>
							) : null}
							{tools.length ? (
								<>
									<dt className="text-muted-foreground">Tools</dt>
									<dd className="flex min-w-0 items-center gap-2 text-foreground">
										<span className="flex -space-x-1">
											{tools.map((tool) =>
												tool.icon ? (
													<MarkTile key={tool.id} className="text-foreground ring-2 ring-card">
														{tool.icon}
													</MarkTile>
												) : null,
											)}
										</span>
										<span title={tools.map((tool) => tool.label).join(', ')} className="truncate">
											{tools.map((tool) => tool.label).join(', ')}
										</span>
									</dd>
								</>
							) : null}
						</dl>
					) : null}
					{steps.length ? (
						<ol className="flex flex-col gap-1.5 border-t border-border px-4 py-3 text-[0.8125rem] text-muted-foreground">
							{steps.map((step, index) => (
								<li key={index} className="flex gap-3">
									<span className="w-3 shrink-0 text-end tabular-nums text-subtle-foreground">{index + 1}</span>
									<span className="min-w-0 text-pretty [overflow-wrap:anywhere]">{step}</span>
								</li>
							))}
						</ol>
					) : null}
				</CollapsiblePanel>
			</Collapsible>
			{actions.length ? (
				<div className="flex flex-wrap items-center gap-2 border-t border-border p-2">
					{chosen ? (
						<span className="inline-flex min-h-7 max-w-full items-center gap-1.5 rounded-md bg-muted px-2 py-1 text-[0.8125rem] text-foreground [overflow-wrap:anywhere]">
							<Check aria-hidden="true" className={cn('size-3.5 shrink-0', iconEnterClass)} />
							{chosen.chosenLabel ?? chosen.label}
						</span>
					) : (
						actions.map((action, index) => (
							<Button
								key={action.id}
								size="xs"
								wrap
								variant={action.variant ?? (index === 0 ? 'default' : 'outline')}
								onClick={() => onAction?.(action.id)}
							>
								{action.label}
							</Button>
						))
					)}
				</div>
			) : null}
		</div>
	);
}

export { AgentDraftCard };
export type { AgentDraftCardProps, AgentDraftAction, AgentDraftTool };

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import { TextShimmer } from '@/components/ui/ai/text-shimmer';

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeToReducedMotion(onStoreChange: () => void) {
	if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
		return () => {};
	}
	const mediaQuery = window.matchMedia(REDUCED_MOTION_QUERY);
	mediaQuery.addEventListener('change', onStoreChange);
	return () => mediaQuery.removeEventListener('change', onStoreChange);
}

function getReducedMotionSnapshot() {
	return typeof window === 'undefined' || typeof window.matchMedia !== 'function'
		? true
		: window.matchMedia(REDUCED_MOTION_QUERY).matches;
}

/** Chevron wavefront across a 3×3 grid (Drive / Dots). */
const chevronDelays = Array.from({ length: 9 }, (_, i) => {
	const r = Math.floor(i / 3);
	const c = i % 3;
	return (c + Math.abs(r - 1)) * 90;
});

const ORBIT_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const orbitDelays = Array.from({ length: 9 }, (_, i) => {
	const k = ORBIT_ORDER.indexOf(i);
	return k === -1 ? null : k * 110;
});

type PixelVariant = 'drive' | 'dots' | 'orbit';

const PIXEL_PATTERNS: Record<
	PixelVariant,
	{ delays: (number | null)[]; durationMs: number; round: boolean }
> = {
	drive: { delays: chevronDelays, durationMs: 650, round: false },
	dots: { delays: chevronDelays, durationMs: 650, round: true },
	orbit: { delays: orbitDelays, durationMs: 950, round: false },
};

type SimpleVariant =
	| 'circular'
	| 'bounce-dots'
	| 'typing'
	| 'wave'
	| 'pulse-dot'
	| 'text-shimmer'
	| 'loading-dots';

type AgentLoaderVariant = PixelVariant | SimpleVariant;

type AgentLoaderProps = {
	variant?: AgentLoaderVariant;
	/** Status label (pixel + text variants). */
	label?: string;
	/** Show a live elapsed timer next to the pixel loader. */
	showElapsed?: boolean;
	/** When provided, use this elapsed ms instead of an internal clock. */
	elapsedMs?: number;
	size?: 'sm' | 'md' | 'lg';
	className?: string;
	text?: string;
};

function formatElapsed(totalSeconds: number): string {
	if (totalSeconds < 60) return `${totalSeconds.toFixed(1)}s`;
	const minutes = Math.floor(totalSeconds / 60);
	const seconds = totalSeconds % 60;
	return `${minutes}m ${seconds.toFixed(1)}s`;
}

function useElapsedSeconds(enabled: boolean, controlledMs?: number) {
	const [ticks, setTicks] = React.useState(0);
	React.useEffect(() => {
		if (!enabled || controlledMs !== undefined) return;
		const id = window.setInterval(() => setTicks((value) => value + 1), 100);
		return () => window.clearInterval(id);
	}, [enabled, controlledMs]);
	if (controlledMs !== undefined) return controlledMs / 1000;
	return ticks / 10;
}

function PixelGrid({
	variant,
	reducedMotion,
}: {
	variant: PixelVariant;
	reducedMotion: boolean;
}) {
	const { delays, durationMs, round } = PIXEL_PATTERNS[variant];
	return (
		<span aria-hidden className="grid grid-cols-[repeat(3,4px)] gap-[1.5px]">
			{delays.map((delay, index) => (
				<span
					key={index}
					className={cn(
						'size-1 bg-foreground',
						round ? 'rounded-full' : 'rounded-[1px]',
					)}
					style={{
						opacity: delay === null ? 0.07 : 0.15,
						animation:
							reducedMotion || delay === null
								? 'none'
								: `ai-pixel-on ${durationMs}ms ease-in-out ${delay}ms infinite`,
					}}
				/>
			))}
		</span>
	);
}

function sizeClass(size: 'sm' | 'md' | 'lg') {
	return { sm: 'size-4', md: 'size-5', lg: 'size-6' }[size];
}

function CircularLoader({ size, className }: { size: 'sm' | 'md' | 'lg'; className?: string }) {
	return (
		<span
			className={cn(
				'inline-block animate-spin rounded-full border-2 border-primary border-t-transparent motion-reduce:animate-none',
				sizeClass(size),
				className,
			)}
			aria-hidden
		/>
	);
}

function DotsBounce({ size, className }: { size: 'sm' | 'md' | 'lg'; className?: string }) {
	const dot = { sm: 'size-1.5', md: 'size-2', lg: 'size-2.5' }[size];
	return (
		<span className={cn('inline-flex items-center gap-1', className)} aria-hidden>
			{[0, 1, 2].map((i) => (
				<span
					key={i}
					className={cn(
						'rounded-full bg-primary animate-[ai-bounce-dots_1.4s_ease-in-out_infinite] motion-reduce:animate-none',
						dot,
					)}
					style={{ animationDelay: `${i * 160}ms` }}
				/>
			))}
		</span>
	);
}

function TypingLoader({ size, className }: { size: 'sm' | 'md' | 'lg'; className?: string }) {
	const dot = { sm: 'size-1', md: 'size-1.5', lg: 'size-2' }[size];
	return (
		<span className={cn('inline-flex items-center gap-1', className)} aria-hidden>
			{[0, 1, 2].map((i) => (
				<span
					key={i}
					className={cn(
						'rounded-full bg-primary animate-[ai-typing_1s_infinite] motion-reduce:animate-none',
						dot,
					)}
					style={{ animationDelay: `${i * 250}ms` }}
				/>
			))}
		</span>
	);
}

function WaveLoader({ size, className }: { size: 'sm' | 'md' | 'lg'; className?: string }) {
	const heights = {
		sm: ['6px', '9px', '12px', '9px', '6px'],
		md: ['8px', '12px', '16px', '12px', '8px'],
		lg: ['10px', '15px', '20px', '15px', '10px'],
	}[size];
	return (
		<span className={cn('inline-flex items-center gap-0.5', sizeClass(size), className)} aria-hidden>
			{heights.map((height, i) => (
				<span
					key={i}
					className="w-0.5 rounded-full bg-primary animate-[ai-wave_1s_ease-in-out_infinite] motion-reduce:animate-none"
					style={{ height, animationDelay: `${i * 100}ms` }}
				/>
			))}
		</span>
	);
}

function PulseDot({ size, className }: { size: 'sm' | 'md' | 'lg'; className?: string }) {
	const dot = { sm: 'size-1', md: 'size-2', lg: 'size-3' }[size];
	return (
		<span
			className={cn(
				'inline-block rounded-full bg-primary animate-[ai-pulse-dot_1.2s_ease-in-out_infinite] motion-reduce:animate-none',
				dot,
				className,
			)}
			aria-hidden
		/>
	);
}

/**
 * Agent loading indicator. Pixel variants (drive / dots / orbit) give the
 * agent a distinct presence; simple variants cover common chat spinners.
 */
function AgentLoader({
	variant = 'drive',
	label = 'Working',
	showElapsed = true,
	elapsedMs,
	size = 'md',
	className,
	text,
}: AgentLoaderProps) {
	const reducedMotion = React.useSyncExternalStore(
		subscribeToReducedMotion,
		getReducedMotionSnapshot,
		() => true,
	);
	const isPixel = variant === 'drive' || variant === 'dots' || variant === 'orbit';
	const elapsed = useElapsedSeconds(isPixel && showElapsed, elapsedMs);
	const statusText = text ?? label;

	if (isPixel) {
		return (
			<span
				data-slot="agent-loader"
				data-variant={variant}
				role="status"
				aria-live="polite"
				className={cn('inline-flex w-fit items-center gap-2.5', className)}
			>
				<PixelGrid variant={variant} reducedMotion={reducedMotion} />
				<TextShimmer className="text-[0.8125rem]">{statusText}</TextShimmer>
				{showElapsed ? (
					<span className="font-mono text-xs tabular-nums text-muted-foreground">
						{formatElapsed(elapsed)}
					</span>
				) : null}
				<span className="sr-only">
					{statusText}
					{showElapsed ? `, ${formatElapsed(elapsed)}` : ''}
				</span>
			</span>
		);
	}

	if (variant === 'text-shimmer') {
		return (
			<span data-slot="agent-loader" role="status" className={cn('inline-flex', className)}>
				<TextShimmer className={cn(size === 'sm' && 'text-xs', size === 'lg' && 'text-base')}>
					{statusText}
				</TextShimmer>
			</span>
		);
	}

	if (variant === 'loading-dots') {
		return (
			<span
				data-slot="agent-loader"
				role="status"
				className={cn('inline-flex items-center gap-0.5 font-medium text-link', className)}
			>
				<span className={cn(size === 'sm' && 'text-xs', size === 'md' && 'text-sm', size === 'lg' && 'text-base')}>
					{statusText}
				</span>
				<span aria-hidden className="inline-flex">
					{[0, 1, 2].map((i) => (
						<span
							key={i}
							className="animate-[ai-loading-dots_1.4s_infinite] motion-reduce:animate-none"
							style={{ animationDelay: `${(i + 1) * 0.2}s` }}
						>
							.
						</span>
					))}
				</span>
			</span>
		);
	}

	const indicator =
		variant === 'circular' ? (
			<CircularLoader size={size} />
		) : variant === 'bounce-dots' ? (
			<DotsBounce size={size} />
		) : variant === 'typing' ? (
			<TypingLoader size={size} />
		) : variant === 'wave' ? (
			<WaveLoader size={size} />
		) : (
			<PulseDot size={size} />
		);

	return (
		<span
			data-slot="agent-loader"
			data-variant={variant}
			role="status"
			aria-live="polite"
			className={cn('inline-flex items-center gap-2', className)}
		>
			{indicator}
			{statusText ? <span className="sr-only">{statusText}</span> : <span className="sr-only">Loading</span>}
		</span>
	);
}

/** @deprecated Prefer AgentLoader — alias kept for prompt-kit familiarity. */
const Loader = AgentLoader;

export { AgentLoader, Loader };
export type { AgentLoaderProps, AgentLoaderVariant, PixelVariant, SimpleVariant };

'use client';

import { ArrowUp, Check, X } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';

type ApprovalOption = {
	id: string;
	label: React.ReactNode;
	description?: React.ReactNode;
};

type ApprovalQuestion = {
	id: string;
	prompt: React.ReactNode;
	type?: 'single' | 'multiple';
	options: ApprovalOption[];
};

type ApprovalCardProps = {
	/** Single-shot confirm (desktop tool-confirm style). */
	title?: React.ReactNode;
	description?: React.ReactNode;
	/** Multi-step questions (Beautiful approval). */
	questions?: ApprovalQuestion[];
	confirmLabel?: string;
	skipLabel?: string;
	destructive?: boolean;
	/** Preview node under the title (tables, diffs, etc.). */
	preview?: React.ReactNode;
	/** A small line above the title in single-confirm mode, e.g. why the run paused. */
	eyebrow?: React.ReactNode;
	onConfirm?: (payload: { answers?: Record<string, string[]> }) => void;
	onSkip?: () => void;
	onDismiss?: () => void;
	className?: string;
	/** Controlled sent state for demos. */
	defaultSent?: boolean;
};

/**
 * Human-in-the-loop approval: simple confirm/skip or multi-question flow.
 */
function ApprovalCard({
	title,
	description,
	questions,
	confirmLabel = 'Confirm',
	skipLabel = 'Skip',
	destructive = false,
	preview,
	eyebrow,
	onConfirm,
	onSkip,
	onDismiss,
	className,
	defaultSent = false,
}: ApprovalCardProps) {
	const multi = Boolean(questions?.length);
	const [qi, setQi] = React.useState(0);
	const [answers, setAnswers] = React.useState<Record<string, string[]>>({});
	const [sent, setSent] = React.useState(defaultSent);

	const question = multi ? questions![qi] : null;
	const selected = question ? (answers[question.id] ?? []) : [];
	const last = multi ? qi === questions!.length - 1 : true;

	const toggleOption = (optionId: string) => {
		if (!question) return;
		const type = question.type ?? 'single';
		setAnswers((prev) => {
			const current = prev[question.id] ?? [];
			const next =
				type === 'single'
					? [optionId]
					: current.includes(optionId)
						? current.filter((id) => id !== optionId)
						: [...current, optionId];
			return { ...prev, [question.id]: next };
		});
		if ((question.type ?? 'single') === 'single') {
			window.setTimeout(() => {
				if (last) {
					setSent(true);
					onConfirm?.({
						answers: {
							...answers,
							[question.id]: [optionId],
						},
					});
				} else {
					setQi((i) => i + 1);
				}
			}, 280);
		}
	};

	const submitMulti = () => {
		if (!question) return;
		if (last) {
			setSent(true);
			onConfirm?.({ answers });
		} else {
			setQi((i) => i + 1);
		}
	};

	if (sent) {
		return (
			<div
				data-slot="approval-card"
				className={cn(
					'flex min-h-28 w-full max-w-sm flex-col items-center justify-center gap-2 rounded-lg bg-card p-4 shadow-card',
					className,
				)}
			>
				<span className="flex size-6 items-center justify-center rounded-full bg-success text-white animate-[ai-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both]">
					<Check className="size-3.5" strokeWidth={3} />
				</span>
				<span className="text-[0.8125rem] font-medium text-foreground">Approved</span>
			</div>
		);
	}

	// Simple confirm (desktop tool-confirm)
	if (!multi) {
		return (
			<div
				data-slot="approval-card"
				data-destructive={destructive ? 'true' : 'false'}
				className={cn(
					'w-full max-w-md overflow-hidden rounded-lg bg-card shadow-card',
					destructive ? 'border-destructive/35' : 'border-border',
					className,
				)}
			>
				<div className="flex items-start justify-between gap-2 px-3 pt-3">
					<div className="min-w-0 space-y-1">
						{eyebrow ? (
							<div className="mb-1.5 flex min-h-4 items-center gap-1.5 text-xs text-muted-foreground [&_svg]:size-3.5 [&_svg]:shrink-0">{eyebrow}</div>
						) : null}
						{title ? (
							<div className="text-[0.8125rem] font-medium text-pretty text-foreground [overflow-wrap:anywhere]">{title}</div>
						) : null}
						{description ? (
							<div className="text-xs text-pretty text-muted-foreground [overflow-wrap:anywhere]">{description}</div>
						) : null}
					</div>
					{onDismiss ? (
						<Button
							type="button"
							variant="ghost"
							size="icon-xs"
							aria-label="Dismiss"
							onClick={onDismiss}
						>
							<X className="size-3.5" />
						</Button>
					) : null}
				</div>
				{preview ? <div className="min-w-0 overflow-x-auto px-3 pt-2 [overflow-wrap:anywhere]">{preview}</div> : null}
				<div className="flex flex-wrap items-center justify-end gap-1.5 p-3">
					{onSkip ? (
						<Button type="button" variant="secondary" size="sm" wrap onClick={onSkip}>
							{skipLabel}
						</Button>
					) : null}
					<Button
						type="button"
						size="sm"
						wrap
						variant={destructive ? 'destructive' : 'default'}
						onClick={() => {
							setSent(true);
							onConfirm?.({});
						}}
					>
						{confirmLabel}
					</Button>
				</div>
			</div>
		);
	}

	// Multi-question flow
	const progress = questions!.map((_, i) => i <= qi);
	const canAdvance = selected.length > 0;

	return (
		<div
			data-slot="approval-card"
			className={cn(
				'w-full max-w-sm overflow-hidden rounded-lg shadow-card',
				className,
			)}
		>
			<div
				key={question!.id}
				className="p-3 animate-[ai-fade-up_300ms_cubic-bezier(0.23,1,0.32,1)_both] motion-reduce:animate-none"
			>
				<div className="flex items-start justify-between gap-2">
					<div className="min-w-0 text-[0.8125rem] font-medium text-pretty text-foreground [overflow-wrap:anywhere]">{question!.prompt}</div>
					<div className="flex shrink-0 items-center gap-1">
						{/* Progress pills, only when there is progress to show. */}
						<div className={cn('flex items-center gap-0.5', progress.length < 2 && 'hidden')} aria-hidden>
							{progress.map((on, i) => (
								<span
									key={i}
									className={cn(
										'h-1 rounded-full transition-[width,background-color] duration-(--duration-slow)',
										on ? 'w-3 bg-primary' : 'w-1.5 bg-border',
									)}
								/>
							))}
						</div>
						{onDismiss ? (
							<Button type="button" variant="ghost" size="icon-xs" aria-label="Dismiss" onClick={onDismiss}>
								<X className="size-3.5" />
							</Button>
						) : null}
					</div>
				</div>
				<div className="mt-2 flex flex-col gap-0.5">
					{question!.options.map((option) => {
						const on = selected.includes(option.id);
						return (
							<button
								key={option.id}
								type="button"
								aria-pressed={on}
								onClick={() => toggleOption(option.id)}
								className={cn(
									// card rounded-lg + p-3 → option rows use rounded-md (concentric)
									'-mx-1.5 flex min-h-10 gap-2 rounded-md px-1.5 py-1.5 text-start text-[0.8125rem]',
									option.description ? 'items-start' : 'items-center',
									'transition-[box-shadow] duration-(--duration-moderate) hover:bg-accent',
									'focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50',
									on && 'bg-accent',
								)}
							>
								<span
									className={cn(
										'flex size-4 shrink-0 items-center justify-center rounded-full border',
										option.description && 'mt-0.5',
										on ? 'border-primary bg-primary text-primary-foreground' : 'border-border',
									)}
								>
									{on ? <Check className="size-2.5" strokeWidth={3} /> : null}
								</span>
								<span className="min-w-0">
									<span className="font-medium text-foreground [overflow-wrap:anywhere]">{option.label}</span>
									{option.description ? (
										<span className="mt-0.5 block text-xs text-muted-foreground [overflow-wrap:anywhere]">{option.description}</span>
									) : null}
								</span>
							</button>
						);
					})}
				</div>
				{(question!.type === 'multiple' || !last) && (
					<div className="mt-2 flex justify-end">
						<Button
							type="button"
							size="icon-sm"
							aria-label={last ? confirmLabel : 'Next'}
							disabled={!canAdvance}
							onClick={submitMulti}
						>
							<ArrowUp className="size-4" />
						</Button>
					</div>
				)}
			</div>
		</div>
	);
}

export { ApprovalCard };
export type { ApprovalCardProps, ApprovalQuestion, ApprovalOption };

'use client';

import { ChevronDown, ChevronUp, CircleCheck, CircleHelp } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { iconEnterClass } from '@/components/ui/ai/mark-tile';

type AskOption = {
	id: string;
	label: React.ReactNode;
};

type AskQuestion = {
	id: string;
	question: React.ReactNode;
	options: AskOption[];
	/** Adds a free-text "Something else" row. Defaults to true. */
	allowOther?: boolean;
};

type AskChoice = { option: string } | { other: string };

type AskAnswer = { choices: Record<string, AskChoice> } | { skipped: true };

type AskCardProps = Omit<React.ComponentProps<'div'>, 'onSubmit'> & {
	questions: AskQuestion[];
	/** Settled answer. When set, the card collapses to a read-only summary. */
	answer?: AskAnswer;
	onSubmit?: (choices: Record<string, AskChoice>) => void;
	onSkip?: () => void;
	continueLabel?: React.ReactNode;
	skipLabel?: React.ReactNode;
	/** Name and placeholder of the free-text row. */
	otherLabel?: string;
	/** A small line above the question, e.g. who is asking or why the run paused. */
	eyebrow?: React.ReactNode;
	/** Glyph beside each question. Defaults to a help circle; `null` leaves the question bare, e.g. under an eyebrow. */
	icon?: React.ReactNode;
	disabled?: boolean;
};

function QuestionHeading({ id, icon, children }: { id?: string; icon?: React.ReactNode; children: React.ReactNode }) {
	const glyph = icon === undefined ? <CircleHelp /> : icon;
	return (
		<div className="flex items-start gap-2">
			{glyph ? (
				<span aria-hidden="true" className="flex h-5 shrink-0 items-center text-muted-foreground [&_svg]:size-4">
					{glyph}
				</span>
			) : null}
			<p id={id} className="min-w-0 text-pretty text-sm font-medium text-foreground [overflow-wrap:anywhere]">
				{children}
			</p>
		</div>
	);
}

/** Radio dot: a ring at rest, a filled disc with a pip once chosen. */
function RadioMark({ checked }: { checked: boolean }) {
	return (
		<span
			aria-hidden="true"
			className={cn(
				'mt-0.5 grid size-4 shrink-0 place-items-center rounded-full border',
				checked ? 'border-primary bg-primary' : 'border-subtle-foreground/50',
			)}
		>
			{checked ? <span className={cn('size-1.5 rounded-full bg-primary-foreground', iconEnterClass)} /> : null}
		</span>
	);
}

function AskQuestionField({
	question,
	choice,
	onChoose,
	otherLabel,
	icon,
	disabled,
}: {
	question: AskQuestion;
	choice: AskChoice | undefined;
	onChoose: (choice: AskChoice | undefined) => void;
	otherLabel: string;
	icon?: React.ReactNode;
	disabled?: boolean;
}) {
	const headingId = React.useId();
	const otherValue = choice && 'other' in choice ? choice.other : '';
	// Card p-3 → rows bleed 6px into the padding and round at radius-md, so labels line up with the heading.
	const rowClass =
		'-mx-1.5 flex min-h-8 items-start gap-2.5 rounded-md px-1.5 py-1.5 text-start text-sm outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50';

	return (
		<div className="flex flex-col gap-2">
			<QuestionHeading id={headingId} icon={icon}>
				{question.question}
			</QuestionHeading>
			<div role="radiogroup" aria-labelledby={headingId} className="flex flex-col gap-0.5">
				{question.options.map((option) => {
					const checked = Boolean(choice && 'option' in choice && choice.option === option.id);
					return (
						<button
							key={option.id}
							type="button"
							role="radio"
							aria-checked={checked}
							disabled={disabled}
							onClick={() => onChoose({ option: option.id })}
							className={cn(
								rowClass,
								'cursor-pointer hover:bg-overlay-hover disabled:cursor-not-allowed disabled:opacity-64',
								checked ? 'bg-overlay-hover text-foreground' : 'text-muted-foreground hover:text-foreground',
							)}
						>
							<RadioMark checked={checked} />
							<span className="min-w-0 flex-1 [overflow-wrap:anywhere]">{option.label}</span>
						</button>
					);
				})}
				{question.allowOther !== false ? (
					<label className={cn(rowClass, 'cursor-text focus-within:bg-overlay-hover', otherValue && 'bg-overlay-hover')}>
						<RadioMark checked={Boolean(otherValue)} />
						<input
							type="text"
							value={otherValue}
							disabled={disabled}
							placeholder={`${otherLabel}…`}
							aria-label={otherLabel}
							onChange={(event) => onChoose(event.target.value ? { other: event.target.value } : undefined)}
							className="min-w-0 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-subtle-foreground pointer-coarse:text-base"
						/>
					</label>
				) : null}
			</div>
		</div>
	);
}

function AnswerChip({ children, muted }: { children: React.ReactNode; muted?: boolean }) {
	return (
		<span
			className={cn(
				'inline-flex h-6 max-w-full items-center gap-1.5 rounded-md border border-border bg-muted px-1.5 text-[0.8125rem]',
				muted ? 'text-muted-foreground' : 'text-foreground',
			)}
		>
			{muted ? null : (
				<CircleCheck aria-hidden="true" className={cn('size-3.5 shrink-0 fill-primary text-primary-foreground', iconEnterClass)} />
			)}
			<span title={typeof children === 'string' ? children : undefined} className="truncate">
				{children}
			</span>
		</span>
	);
}

/**
 * Inline clarifying questions from an agent, one at a time. Each question
 * offers its options as radio rows plus a free-text row; Continue moves to the
 * next question and submits after the last. The card settles into a one-line
 * summary per question once answered or skipped.
 */
function AskCard({
	questions,
	answer,
	onSubmit,
	onSkip,
	continueLabel = 'Continue',
	skipLabel = 'Skip',
	otherLabel = 'Something else',
	eyebrow,
	icon,
	disabled,
	className,
	...props
}: AskCardProps) {
	const [choices, setChoices] = React.useState<Record<string, AskChoice>>({});
	const [page, setPage] = React.useState(0);
	const answered = (question: AskQuestion | undefined) => {
		const choice = question ? choices[question.id] : undefined;
		return Boolean(choice && ('option' in choice || choice.other.trim().length > 0));
	};
	const complete = questions.every(answered);
	const current = questions[Math.min(page, questions.length - 1)];
	const last = page >= questions.length - 1;
	const paged = questions.length > 1;

	if (answer) {
		return (
			<div
				data-slot="ask-card"
				data-state="answered"
				className={cn('flex animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] flex-col gap-1 motion-reduce:animate-none', className)}
				{...props}
			>
				{questions.map((question) => {
					const choice = 'choices' in answer ? answer.choices[question.id] : undefined;
					const label = choice
						? 'option' in choice
							? question.options.find((option) => option.id === choice.option)?.label
							: `“${choice.other}”`
						: undefined;
					return (
						// The icon keeps its own column, so a long question wraps beside it instead of below it.
						<div key={question.id} className="flex items-start gap-2">
							<CircleHelp aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
							<div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
								<p className="min-w-0 text-pretty text-sm text-foreground [overflow-wrap:anywhere]">{question.question}</p>
								{label ? <AnswerChip>{label}</AnswerChip> : <AnswerChip muted>Skipped</AnswerChip>}
							</div>
						</div>
					);
				})}
			</div>
		);
	}

	return (
		<div
			data-slot="ask-card"
			data-state="open"
			className={cn('flex animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] flex-col gap-3 rounded-xl bg-card p-3 shadow-card motion-reduce:animate-none', className)}
			{...props}
		>
			{eyebrow ? <div className="-mb-1 flex min-h-4 items-center gap-1.5 text-xs text-muted-foreground [&_svg]:size-3.5 [&_svg]:shrink-0">{eyebrow}</div> : null}
			{current ? (
				// Keyed by question, so each page enters on its own.
				<div key={current.id} className="animate-[ai-fade-up_var(--duration-slow)_var(--ease-out)_both] motion-reduce:animate-none">
					<AskQuestionField
						question={current}
						choice={choices[current.id]}
						disabled={disabled}
						otherLabel={otherLabel}
						icon={icon}
						onChoose={(choice) =>
							setChoices((value) => {
								const next = { ...value };
								if (choice) next[current.id] = choice;
								else delete next[current.id];
								return next;
							})
						}
					/>
				</div>
			) : null}
			<div className="flex flex-wrap items-center gap-2">
				{paged ? (
					<div className="-ms-1 flex items-center text-xs text-muted-foreground tabular-nums">
						<Button size="icon-xs" variant="ghost" aria-label="Previous question" disabled={page === 0} onClick={() => setPage(page - 1)}>
							<ChevronUp aria-hidden="true" />
						</Button>
						<span aria-hidden="true">
							{page + 1}/{questions.length}
						</span>
						<span className="sr-only">
							Question {page + 1} of {questions.length}
						</span>
						<Button size="icon-xs" variant="ghost" aria-label="Next question" disabled={last || !answered(current)} onClick={() => setPage(page + 1)}>
							<ChevronDown aria-hidden="true" />
						</Button>
					</div>
				) : null}
				<div className="ms-auto flex flex-wrap items-center gap-1.5">
					{onSkip ? (
						<Button size="sm" variant="secondary" disabled={disabled} onClick={onSkip}>
							{skipLabel}
						</Button>
					) : null}
					<Button
						size="sm"
						disabled={disabled || (last ? !complete : !answered(current))}
						onClick={() => (last ? onSubmit?.(choices) : setPage(page + 1))}
					>
						{continueLabel}
					</Button>
				</div>
			</div>
		</div>
	);
}

export { AskCard };
export type { AskCardProps, AskQuestion, AskOption, AskChoice, AskAnswer };

'use client';

import * as React from 'react';

import { useMergedRefs } from '@/lib/compose-refs';
import { cn } from '@/lib/utils';

type ChatContainerContextValue = {
	scrollRef: React.RefObject<HTMLDivElement | null>;
	isAtBottom: boolean;
	scrollToBottom: (behavior?: ScrollBehavior) => void;
};

const ChatContainerContext = React.createContext<ChatContainerContextValue | null>(null);

function useChatContainer() {
	const context = React.useContext(ChatContainerContext);
	if (!context) {
		throw new Error('useChatContainer must be used within ChatContainer.');
	}
	return context;
}

type ChatContainerProps = React.ComponentProps<'div'> & {
	/** Pixels from the bottom that still count as "pinned". */
	bottomThreshold?: number;
	/** Auto-follow new content while pinned to the bottom. */
	autoScroll?: boolean;
};

/**
 * Scroll region for chat transcripts with stick-to-bottom tracking.
 * Pair with ScrollButton for jump-to-latest.
 */
function ChatContainer({
	className,
	children,
	bottomThreshold = 48,
	autoScroll = true,
	ref,
	...props
}: ChatContainerProps) {
	const scrollRef = React.useRef<HTMLDivElement>(null);
	// The caller's ref joins the container's own, so passing one can't cut off the stick-to-bottom tracking.
	const mergedRef = useMergedRefs(scrollRef, ref);
	const [isAtBottom, setIsAtBottom] = React.useState(true);
	const isAtBottomRef = React.useRef(true);

	const scrollToBottom = React.useCallback((behavior: ScrollBehavior = 'smooth') => {
		const node = scrollRef.current;
		if (!node) return;
		node.scrollTo({ top: node.scrollHeight, behavior });
	}, []);

	const updatePinned = React.useCallback(() => {
		const node = scrollRef.current;
		if (!node) return;
		const distance = node.scrollHeight - node.scrollTop - node.clientHeight;
		const pinned = distance <= bottomThreshold;
		isAtBottomRef.current = pinned;
		setIsAtBottom(pinned);
	}, [bottomThreshold]);

	React.useEffect(() => {
		const node = scrollRef.current;
		if (!node) return;
		updatePinned();
		node.addEventListener('scroll', updatePinned, { passive: true });
		const observer = new ResizeObserver(() => {
			if (autoScroll && isAtBottomRef.current) {
				node.scrollTop = node.scrollHeight;
			}
			updatePinned();
		});
		observer.observe(node);
		if (node.firstElementChild) observer.observe(node.firstElementChild);
		return () => {
			node.removeEventListener('scroll', updatePinned);
			observer.disconnect();
		};
	}, [autoScroll, updatePinned]);

	// Follow content growth while pinned.
	React.useLayoutEffect(() => {
		if (!autoScroll || !isAtBottomRef.current) return;
		const node = scrollRef.current;
		if (!node) return;
		node.scrollTop = node.scrollHeight;
	});

	return (
		<ChatContainerContext.Provider value={{ scrollRef, isAtBottom, scrollToBottom }}>
			<div
				ref={mergedRef}
				data-slot="chat-container"
				data-at-bottom={isAtBottom ? 'true' : 'false'}
				className={cn('relative min-h-0 flex-1 overflow-y-auto overscroll-contain', className)}
				{...props}
			>
				{children}
			</div>
		</ChatContainerContext.Provider>
	);
}

type ChatContainerContentProps = React.ComponentProps<'div'>;

function ChatContainerContent({ className, ...props }: ChatContainerContentProps) {
	return (
		<div
			data-slot="chat-container-content"
			className={cn('mx-auto flex w-full max-w-2xl flex-col gap-4 px-4 py-6', className)}
			{...props}
		/>
	);
}

export { ChatContainer, ChatContainerContent, useChatContainer };
export type { ChatContainerProps, ChatContainerContentProps };

'use client';

import { Check, ChevronDown, Copy } from 'lucide-react';
import * as React from 'react';
import { highlight } from 'sugar-high';
import { c, css, diff, go, java, python, rust } from 'sugar-high/presets';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';

/** Default visible lines before the expand control appears. */
const DEFAULT_COLLAPSED_LINES = 12;
/** Approx. line box for text-xs + leading-relaxed (+ padding slack). */
const LINE_BOX_PX = 20;
/** Vertical padding inside the pre (p-3 = 12px × 2). */
const PRE_PAD_Y = 24;

type CodeBlockProps = React.ComponentProps<'div'> & {
	code: string;
	language?: string;
	/** Optional filename shown in the header. */
	filename?: string;
	/** Show the copy control (default true). */
	showCopy?: boolean;
	/**
	 * Syntax highlighting via sugar-high (~1 kB). Default true.
	 * Disable for ultra-hot streaming paths if the host re-highlights later.
	 */
	highlight?: boolean;
	/**
	 * Max lines shown while collapsed. Pass `false` to always show full code.
	 * Default 12. Collapse only engages when the source is longer.
	 */
	maxCollapsedLines?: number | false;
	/**
	 * When expanded, cap height and scroll inside the block.
	 * Pass `false` for fully unconstrained height. Default ~28rem / 70vh.
	 */
	maxExpandedHeight?: string | false;
	/** Controlled expand state. */
	expanded?: boolean;
	/** Uncontrolled initial expand. Default false. */
	defaultExpanded?: boolean;
	onExpandedChange?: (expanded: boolean) => void;
	/** Reveal code line-by-line for demos / progressive stream. */
	streamingLines?: boolean;
	/** Lines revealed per tick when streamingLines is true. */
	lineIntervalMs?: number;
};

/** Map common language labels to sugar-high presets (JS/TS/JSX is the default). */
function optionsForLanguage(language?: string) {
	if (!language) return undefined;
	const key = language.toLowerCase().trim();
	switch (key) {
		case 'ts':
		case 'tsx':
		case 'typescript':
		case 'js':
		case 'jsx':
		case 'javascript':
		case 'mjs':
		case 'cjs':
			return undefined;
		case 'py':
		case 'python':
			return python;
		case 'rs':
		case 'rust':
			return rust;
		case 'go':
		case 'golang':
			return go;
		case 'java':
			return java;
		case 'c':
		case 'h':
		case 'cpp':
		case 'c++':
		case 'cxx':
		case 'cc':
			return c;
		case 'css':
		case 'scss':
		case 'less':
			return css;
		case 'diff':
		case 'patch':
			return diff;
		default:
			return undefined;
	}
}

/**
 * Agent code surface with lightweight sugar-high highlighting, elegant header,
 * copy action, and collapse/expand for long sources.
 */
function CodeBlock({
	code,
	language,
	filename,
	showCopy = true,
	highlight: highlightEnabled = true,
	maxCollapsedLines = DEFAULT_COLLAPSED_LINES,
	maxExpandedHeight = 'min(28rem, 70vh)',
	expanded: expandedProp,
	defaultExpanded = false,
	onExpandedChange,
	streamingLines = false,
	lineIntervalMs = 240,
	className,
	...props
}: CodeBlockProps) {
	const [copied, setCopied] = React.useState(false);
	const [uncontrolledExpanded, setUncontrolledExpanded] = React.useState(defaultExpanded);
	const expanded = expandedProp ?? uncontrolledExpanded;

	const setExpanded = React.useCallback(
		(next: boolean) => {
			if (expandedProp === undefined) setUncontrolledExpanded(next);
			onExpandedChange?.(next);
		},
		[expandedProp, onExpandedChange],
	);

	const lines = React.useMemo(() => code.replace(/\n$/, '').split('\n'), [code]);
	const lineCount = lines.length === 1 && lines[0] === '' ? 0 : lines.length;

	const [visibleCount, setVisibleCount] = React.useState(streamingLines ? 0 : lines.length);

	React.useEffect(() => {
		if (!streamingLines) {
			setVisibleCount(lines.length);
			return;
		}
		setVisibleCount(0);
		if (lines.length === 0) return;
		const id = window.setInterval(() => {
			setVisibleCount((count) => {
				if (count >= lines.length) {
					window.clearInterval(id);
					return count;
				}
				return count + 1;
			});
		}, lineIntervalMs);
		return () => window.clearInterval(id);
	}, [streamingLines, lines, lineIntervalMs, code]);

	const visible = streamingLines ? lines.slice(0, visibleCount).join('\n') : code;

	const highlightedHtml = React.useMemo(() => {
		if (!highlightEnabled || !visible) return null;
		try {
			return highlight(visible, optionsForLanguage(language));
		} catch {
			return null;
		}
	}, [visible, language, highlightEnabled]);

	const handleCopy = React.useCallback(async () => {
		try {
			await navigator.clipboard.writeText(code);
			setCopied(true);
			window.setTimeout(() => setCopied(false), 1500);
		} catch {
			// Clipboard can fail in non-secure contexts; stay quiet.
		}
	}, [code]);

	const collapsible =
		maxCollapsedLines !== false && lineCount > maxCollapsedLines && !streamingLines;
	const isCollapsed = collapsible && !expanded;
	const hiddenLineCount = collapsible ? Math.max(0, lineCount - maxCollapsedLines) : 0;

	const collapsedMaxHeight =
		maxCollapsedLines === false
			? undefined
			: PRE_PAD_Y + maxCollapsedLines * LINE_BOX_PX;

	const hasHeader = Boolean(filename || language || showCopy);

	return (
		<div
			data-slot="code-block"
			data-language={language || undefined}
			data-expanded={collapsible ? expanded : undefined}
			className={cn(
				'overflow-hidden rounded-lg border border-border bg-muted/40 text-sm',
				// sugar-high token colors (light defaults; dark overrides below)
				'[--sh-class:oklch(0.48_0.12_250)] [--sh-identifier:var(--foreground)] [--sh-sign:var(--muted-foreground)]',
				'[--sh-property:oklch(0.48_0.11_230)] [--sh-entity:oklch(0.48_0.1_175)] [--sh-jsxliterals:oklch(0.5_0.14_290)]',
				'[--sh-string:oklch(0.48_0.1_160)] [--sh-keyword:oklch(0.52_0.16_25)] [--sh-comment:var(--muted-foreground)]',
				'[--sh-space:transparent] [--sh-break:transparent]',
				'dark:[--sh-class:oklch(0.78_0.1_250)] dark:[--sh-identifier:oklch(0.93_0_0)]',
				'dark:[--sh-sign:oklch(0.68_0.02_286)] dark:[--sh-property:oklch(0.78_0.1_230)]',
				'dark:[--sh-entity:oklch(0.78_0.1_175)] dark:[--sh-jsxliterals:oklch(0.8_0.12_290)]',
				'dark:[--sh-string:oklch(0.78_0.1_160)] dark:[--sh-keyword:oklch(0.78_0.14_25)]',
				'dark:[--sh-comment:oklch(0.62_0.02_286)]',
				className,
			)}
			{...props}
		>
			{hasHeader ? (
				<div
					data-slot="code-block-header"
					className="flex items-center gap-2 border-b border-border bg-muted/50 px-2.5 py-1.5"
				>
					<div className="flex min-w-0 flex-1 items-center gap-2">
						{filename ? (
							<span
								data-slot="code-block-filename"
								className="min-w-0 truncate font-mono text-[0.75rem] text-foreground/80"
								title={filename}
							>
								{filename}
							</span>
						) : language ? (
							<span
								data-slot="code-block-language"
								className="min-w-0 truncate font-mono text-[0.75rem] text-foreground/80"
							>
								{language}
							</span>
						) : null}

						{filename && language ? (
							<span
								data-slot="code-block-language"
								className={cn(
									'inline-flex shrink-0 items-center rounded-md px-1.5 py-0.5',
									'border border-border bg-background/50',
									'font-sans text-[0.625rem] font-medium tracking-wide text-muted-foreground uppercase',
								)}
							>
								{language}
							</span>
						) : null}

						{/* Quiet line count when long enough to collapse */}
						{collapsible ? (
							<span
								data-slot="code-block-meta"
								className="hidden shrink-0 font-sans text-[0.6875rem] tabular-nums text-muted-foreground/70 sm:inline"
							>
								{lineCount} lines
							</span>
						) : null}
					</div>

					{showCopy ? (
						<Button
							type="button"
							variant="ghost"
							size="icon-xs"
							className="shrink-0 text-muted-foreground hover:text-foreground"
							aria-label={copied ? 'Copied' : 'Copy code'}
							onClick={handleCopy}
						>
							{copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
						</Button>
					) : null}
				</div>
			) : null}

			{/* Body: constrained height + optional fade when collapsed */}
			<div data-slot="code-block-body" className="relative">
				<pre
					className={cn(
						'overflow-x-auto p-3 font-mono text-xs leading-relaxed text-foreground',
						'[&_.sh__line]:block',
						// Soft height transition when toggling expand
						'transition-[max-height] duration-(--duration-slow) ease-out motion-reduce:transition-none',
						isCollapsed && 'overflow-y-hidden',
						!isCollapsed && maxExpandedHeight !== false && collapsible && 'overflow-y-auto',
					)}
					style={
						isCollapsed
							? { maxHeight: collapsedMaxHeight }
							: collapsible && maxExpandedHeight !== false
								? { maxHeight: maxExpandedHeight }
								: undefined
					}
				>
					{highlightedHtml ? (
						<code
							// sugar-high escapes token text and emits only its own span markup
							dangerouslySetInnerHTML={{ __html: highlightedHtml }}
						/>
					) : (
						<code>{visible}</code>
					)}
				</pre>

				{/* Fade into the expand control so the cut isn’t harsh */}
				{isCollapsed ? (
					<div
						aria-hidden
						data-slot="code-block-fade"
						className={cn(
							'pointer-events-none absolute inset-x-0 bottom-0 h-16',
							'bg-linear-to-t from-muted/95 via-muted/55 to-transparent',
							// Match the soft code surface in light/dark
							'dark:from-muted/90 dark:via-muted/50',
						)}
					/>
				) : null}
			</div>

			{collapsible ? (
				<div
					data-slot="code-block-footer"
					className="border-t border-border bg-muted/40"
				>
					<button
						type="button"
						data-slot="code-block-expand"
						aria-expanded={expanded}
						onClick={() => setExpanded(!expanded)}
						className={cn(
							'flex w-full items-center justify-center gap-1.5 px-3 py-2',
							'text-[0.75rem] font-medium text-muted-foreground',
							'outline-none transition-[color,background-color,border-color,text-decoration-color,fill,stroke,box-shadow] duration-(--duration-moderate)',
							'hover:bg-muted/70 hover:text-foreground',
							'focus-visible:bg-muted/70 focus-visible:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:ring-inset',
						)}
					>
						<span>
							{expanded
								? 'Show less'
								: hiddenLineCount === 1
									? 'Show 1 more line'
									: `Show ${hiddenLineCount} more lines`}
						</span>
						<ChevronDown
							className={cn(
								'size-3.5 opacity-70 transition-transform duration-(--duration-slow) ease-out motion-reduce:transition-none',
								expanded && 'rotate-180',
							)}
							aria-hidden
						/>
					</button>
				</div>
			) : null}
		</div>
	);
}

