type MessageContentProps = React.ComponentProps<'div'> & {
	markdown?: boolean;
	/** While true, markdown re-renders are throttled (see Markdown). */
	streaming?: boolean;
};

function MessageContent({
	className,
	markdown = false,
	streaming = false,
	children,
	...props
}: MessageContentProps) {
	// Plain text keeps the line breaks it was typed with, and an unbroken URL wraps inside the bubble.
	const contentClassName = cn(
		'min-w-0 max-w-[min(100%,42rem)] text-sm leading-relaxed text-foreground [overflow-wrap:anywhere]',
		typeof children === 'string' && !markdown && 'whitespace-pre-wrap',
		className,
	);

	if (markdown && typeof children === 'string') {
		return (
			<Markdown
				data-slot="message-content"
				// Each message sets its own direction, so a reply in one script reads right inside a UI in another.
				dir="auto"
				streaming={streaming}
				className={contentClassName}
				{...props}
			>
				{children}
			</Markdown>
		);
	}

	return (
		<div data-slot="message-content" dir="auto" className={contentClassName} {...props}>
			{children}
		</div>
	);
