import { Brain, ChevronDown } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Collapsible, CollapsiblePanel, CollapsibleTrigger } from '@/components/ui/collapsible';
import { formatDuration } from '@/components/ui/ai/format-duration';
import { Markdown } from '@/components/ui/ai/markdown';
import { TextShimmer } from '@/components/ui/ai/text-shimmer';

type ReasoningProps = {
	children?: React.ReactNode;
	/** Raw thinking text; used when children are omitted. */
	content?: string;
	isStreaming?: boolean;
	/** Elapsed thinking time in ms (settled). */
	durationMs?: number | null;
	open?: boolean;
	onOpenChange?: (open: boolean) => void;
	/** Render content as markdown. */
	markdown?: boolean;
	className?: string;
	/** Override trigger label while streaming. */
	streamingLabel?: string;
	/** Override settled label when no duration. */
	doneLabel?: string;
};

/**
 * Collapsible model reasoning / thinking block.
 * Auto-opens while streaming; auto-collapses when settled unless the user toggled.
 */
function Reasoning({
	children,
	content,
	isStreaming = false,
	durationMs = null,
	open: openProp,
	onOpenChange,
	markdown = false,
	className,
	streamingLabel = 'Thinking…',
	doneLabel = 'Thought',
}: ReasoningProps) {
	const [internalOpen, setInternalOpen] = React.useState(isStreaming);
	const userToggled = React.useRef(false);
	const prevStreaming = React.useRef(isStreaming);
	const controlled = openProp !== undefined;
	const open = controlled ? openProp : internalOpen;

	const setOpen = React.useCallback(
		(next: boolean) => {
			if (!controlled) setInternalOpen(next);
			onOpenChange?.(next);
		},
		[controlled, onOpenChange],
	);

	React.useEffect(() => {
		const was = prevStreaming.current;
		prevStreaming.current = isStreaming;
		if (!was && isStreaming) {
			userToggled.current = false;
			if (!controlled) setInternalOpen(true);
			onOpenChange?.(true);
		} else if (was && !isStreaming && !userToggled.current) {
			if (!controlled) setInternalOpen(false);
			onOpenChange?.(false);
		}
	}, [isStreaming, controlled, onOpenChange]);

	const body = children ?? content ?? '';
	const empty = typeof body === 'string' ? body.trim().length === 0 : !body;
	if (empty && !isStreaming) return null;

	const duration =
		durationMs != null && durationMs > 0 ? formatDuration(durationMs) : null;
	const label = isStreaming
		? streamingLabel
		: duration
			? `Thought for ${duration}`
			: doneLabel;

	return (
		<Collapsible
			open={open}
			onOpenChange={(next) => {
				if (isStreaming) userToggled.current = true;
				setOpen(next);
			}}
			className={cn('w-full', className)}
			data-slot="reasoning"
		>
			<CollapsibleTrigger
				className={cn(
					'group -mx-1.5 flex w-fit max-w-full items-center gap-1.5 rounded-md px-1.5 py-1.5 text-start text-[0.8125rem]',
					'text-muted-foreground transition-[box-shadow] duration-(--duration-moderate) hover:bg-accent hover:text-foreground',
					'focus-visible:outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50',
				)}
			>
				<Brain className="size-3.5 shrink-0 opacity-80" />
				{isStreaming ? (
					<TextShimmer className="text-[0.8125rem] font-medium tabular-nums">{label}</TextShimmer>
				) : (
					<span className="font-medium tabular-nums">{label}</span>
				)}
				<ChevronDown
					data-slot="collapsible-icon"
					className="size-3.5 shrink-0 opacity-60 transition-transform duration-(--duration-slow)"
				/>
			</CollapsibleTrigger>
			<CollapsiblePanel innerClassName="py-0">
				<div className="my-1 ms-1.5 border-s border-border/70 py-1 ps-3">
					{markdown && typeof body === 'string' ? (
						<Markdown
							streaming={isStreaming}
							className="text-[0.8125rem] text-muted-foreground"
						>
							{body}
						</Markdown>
					) : (
						<div className="whitespace-pre-wrap text-[0.8125rem] leading-relaxed text-muted-foreground">
							{body}
						</div>
					)}
				</div>
			</CollapsiblePanel>
		</Collapsible>
	);
}

type ThinkingBarProps = {
