		>
			{onClick ? (
				<button
					type="button"
					onClick={onClick}
					className="flex items-center gap-1 text-sm transition-opacity duration-(--duration-moderate) hover:opacity-80"
				>
					<TextShimmer className="font-medium">{text}</TextShimmer>
