	errorText?: string;
	/** Compact detail lines for chip/row expand. */
	detail?: Array<{ text: string; tone?: 'add' | 'default' }>;
	diff?: DiffFileChip | DiffFileChip[];
	variant?: ToolVariant;
	defaultOpen?: boolean;
	open?: boolean;
	onOpenChange?: (open: boolean) => void;
	className?: string;
	children?: React.ReactNode;
};

function formatValue(value: unknown): string {
	if (value === null) return 'null';
	if (value === undefined) return 'undefined';
	if (typeof value === 'string') return value;
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

function StatusIcon({ status }: { status: ReturnType<typeof normalizeToolStatus> }) {
	switch (status) {
		// shrink-0 throughout: a long summary beside the icon must never squeeze it.
		case 'pending':
			return <CircleDashed className="size-3.5 shrink-0 text-muted-foreground" />;
		case 'running':
			return <Loader2 className="size-3.5 shrink-0 animate-spin text-muted-foreground motion-reduce:animate-none" />;
		case 'success':
			return <CheckCircle2 className="size-3.5 shrink-0 text-success" />;
		case 'error':
			return <CircleX className="size-3.5 shrink-0 text-destructive" />;
		case 'aborted':
			return <Ban className="size-3.5 shrink-0 text-muted-foreground" />;
	}
}

function statusBadge(status: ReturnType<typeof normalizeToolStatus>) {
	const map = {
		pending: { label: 'Queued', className: 'bg-info/10 text-info border-info/20' },
		running: { label: 'Running', className: 'bg-warning/10 text-warning border-warning/25' },
		success: { label: 'Done', className: 'bg-success/10 text-success border-success/20' },
		error: { label: 'Error', className: 'bg-destructive/10 text-destructive border-destructive/20' },
		aborted: { label: 'Stopped', className: 'bg-muted text-muted-foreground border-border' },
	} as const;
	return map[status];
}

/**
 * Tool call presentation in card, chip, or compact row density.
 */
function Tool({
	name,
	status: statusProp = 'pending',
	summary,
	input,
	output,
	errorText,
	detail,
	diff,
	variant = 'row',
	defaultOpen = false,
	open,
	onOpenChange,
	className,
	children,
}: ToolProps) {
	const status = normalizeToolStatus(statusProp);
	const diffs = diff ? (Array.isArray(diff) ? diff : [diff]) : [];
	const hasBody =
		Boolean(children) ||
		Boolean(detail?.length) ||
		input !== undefined ||
		output !== undefined ||
		Boolean(errorText) ||
		diffs.length > 0;

	if (variant === 'chip') {
		return (
			<div
				data-slot="tool"
				data-variant="chip"
				data-status={status}
				className={cn(
					'inline-flex max-w-full items-center gap-1.5 rounded-md border border-border bg-muted/40 px-2 py-1 text-[0.75rem]',
					className,
				)}
			>
				<StatusIcon status={status} />
				<span title={name} className="max-w-[9rem] shrink-0 truncate font-medium text-foreground">
					{name}
				</span>
				{summary ? (
					<span dir="auto" title={typeof summary === 'string' ? summary : undefined} className="min-w-0 truncate font-mono text-muted-foreground">
						{summary}
					</span>
				) : null}
			</div>
		);
	}

	const trigger = (
		<span
			className={cn(
				'flex min-w-0 max-w-full items-center gap-1.5 text-[0.8125rem] text-muted-foreground',
				variant === 'card' && 'w-full justify-between font-normal',
			)}
		>
			<span className="flex min-w-0 items-center gap-1.5">
				<StatusIcon status={status} />
				{/* The name and summary share what is left and truncate; the status badge keeps its full width. */}
				<span title={name} className="max-w-[45%] shrink-0 truncate font-medium text-foreground/90">
					{name}
				</span>
				{summary ? (
					<span
						dir="auto"
						title={typeof summary === 'string' ? summary : undefined}
						className={cn(
							'min-w-0 truncate rounded-md bg-muted px-1.5 py-0.5 font-mono text-[0.71875rem] text-muted-foreground',
						)}
					>
						{summary}
					</span>
				) : null}
				{variant === 'card' ? (
					<span
						className={cn(
							'shrink-0 rounded-full border px-2 py-0.5 text-[0.6875rem] font-medium',
							statusBadge(status).className,
						)}
					>
						{statusBadge(status).label}
					</span>
				) : null}
			</span>
			{hasBody ? (
				<ChevronDown
					data-slot="collapsible-icon"
					className="size-3.5 shrink-0 opacity-0 transition-[opacity,transform] duration-(--duration-moderate) group-hover/tool:opacity-100 group-data-[panel-open]/collapsible:opacity-100"
				/>
			) : null}
		</span>
	);

	if (!hasBody) {
		return (
			<div
				data-slot="tool"
				data-variant={variant}
				data-status={status}
				className={cn('flex w-full items-center py-0.5 text-start', className)}
			>
				{trigger}
			</div>
		);
	}

	const body = (
		<div className="space-y-2 text-[0.78125rem]">
			{children}
			{detail?.map((line, i) => (
				<div
					key={i}
					className={cn(
						'font-mono leading-relaxed text-muted-foreground [overflow-wrap:anywhere]',
						line.tone === 'add' && 'text-success',
					)}
				>
					{line.text}
				</div>
			))}
			{input !== undefined ? (
				<section>
					<h4 className="mb-1 text-xs font-medium text-muted-foreground">Input</h4>
					<pre className="max-h-40 overflow-auto rounded-md border border-border bg-background p-2 font-mono text-[0.71875rem] leading-relaxed">
						{formatValue(input)}
					</pre>
				</section>
			) : null}
			{output !== undefined ? (
				<section>
					<h4 className="mb-1 text-xs font-medium text-muted-foreground">Output</h4>
					<pre className="max-h-48 overflow-auto rounded-md border border-border bg-background p-2 font-mono text-[0.71875rem] leading-relaxed">
						{formatValue(output)}
					</pre>
				</section>
			) : null}
			{errorText ? (
				<section className="rounded-md border border-destructive/30 bg-destructive/8 p-2 text-destructive [overflow-wrap:anywhere]">
					{errorText}
				</section>
			) : null}
			{diffs.length > 0 ? (
				<div className="flex flex-wrap gap-1.5 pt-0.5">
					{diffs.map((d) => (
						<span
							key={d.file}
							className="inline-flex max-w-full items-center gap-1.5 rounded-md border border-border bg-muted/50 px-1.5 py-0.5 font-mono text-[0.6875rem]"
						>
							<span title={d.file} className="min-w-0 break-all text-foreground">
								{d.file}
							</span>
							{d.add != null ? <span className="shrink-0 text-success">+{d.add}</span> : null}
							{d.del != null ? <span className="shrink-0 text-destructive">-{d.del}</span> : null}
						</span>
					))}
				</div>
			) : null}
		</div>
	);

	if (variant === 'card') {
		return (
			<div
				data-slot="tool"
				data-variant="card"
				data-status={status}
				className={cn('overflow-hidden rounded-lg border border-border', className)}
			>
				<Collapsible open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} className="group/tool group/collapsible">
					<CollapsibleTrigger className="w-full bg-background px-3 py-2.5 hover:bg-accent/40">
						{trigger}
					</CollapsibleTrigger>
					<CollapsiblePanel className="border-t border-border" innerClassName="px-3 py-2">
						{body}
					</CollapsiblePanel>
				</Collapsible>
			</div>
		);
	}

	// row (Beautiful tool-chips density)
	return (
		<div data-slot="tool" data-variant="row" data-status={status} className={cn('flex flex-col', className)}>
			<Collapsible
				open={open}
				defaultOpen={defaultOpen}
				onOpenChange={onOpenChange}
				className="group/tool group/collapsible"
			>
				<CollapsibleTrigger
					className={cn(
						'group/row -mx-1 flex min-h-8 w-[calc(100%+0.5rem)] min-w-0 items-center gap-2 rounded-md px-1 py-1 text-start',
						'hover:bg-accent',
						'pointer-coarse:min-h-11',
					)}
				>
					{trigger}
				</CollapsibleTrigger>
				<CollapsiblePanel innerClassName="py-1 ps-5">
					{body}
				</CollapsiblePanel>
			</Collapsible>
		</div>
	);
}

type ToolGroupProps = {
	/** e.g. "4 tool calls, 2 messages" */
	label: React.ReactNode;
	children: React.ReactNode;
	defaultOpen?: boolean;
	className?: string;
};

function ToolGroup({ label, children, defaultOpen = true, className }: ToolGroupProps) {
	return (
		<div data-slot="tool-group" className={cn('w-full max-w-md', className)}>
			<Collapsible defaultOpen={defaultOpen} className="group/collapsible">
				<CollapsibleTrigger
					className={cn(
						'-mx-1.5 flex w-fit items-center gap-1.5 rounded-md px-1.5 py-1.5 text-[0.78125rem]',
						'text-muted-foreground hover:bg-accent hover:text-foreground',
					)}
				>
					<ChevronDown data-slot="collapsible-icon" className="size-3.5 shrink-0" />
					<span className="tabular-nums">{label}</span>
				</CollapsibleTrigger>
				<CollapsiblePanel innerClassName="py-1">
					<div className="mt-0.5 flex flex-col gap-1">{children}</div>
				</CollapsiblePanel>
			</Collapsible>
		</div>
	);
}

export { Tool, ToolGroup, StatusIcon };
export type { ToolProps, ToolVariant, ToolGroupProps };

/** Shared presentation types for agent surfaces (host-runtime agnostic). */

export type ToolStatus =
	| 'pending'
	| 'running'
	| 'success'
	| 'error'
	| 'aborted'
	// AI SDK–style part states
	| 'input-streaming'
	| 'input-available'
	| 'output-available'
	| 'output-error';

export type NormalizedToolStatus = 'pending' | 'running' | 'success' | 'error' | 'aborted';

export function normalizeToolStatus(status: ToolStatus | string | undefined): NormalizedToolStatus {
	switch (status) {
		case 'input-streaming':
		case 'pending':
			return 'pending';
		case 'input-available':
		case 'running':
			return 'running';
		case 'output-available':
		case 'success':
			return 'success';
		case 'output-error':
		case 'error':
			return 'error';
		case 'aborted':
			return 'aborted';
		default:
			return 'pending';
	}
}

export type PlanStepStatus = 'pending' | 'in_progress' | 'done';

export type PlanStep = {
	label: string;
	status: PlanStepStatus;
};

export type Plan = {
	steps: PlanStep[];
};

export type ContextUsage = {
	/** null while recomputing after compaction */
	tokens: number | null;
	percent?: number | null;
	contextWindow: number;
};

export type DiffFileChip = {
	file: string;
	add?: number;
	del?: number;
};

export type InlineDiffSource = {
	before: string;
	after: string;
	fileName?: string;
};

'use client';

import { Gauge, TriangleAlert, X } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { PromptInputTrayRow, type PromptInputTrayTone } from '@/components/ui/ai/prompt-input-tray';

/** Tray tone for a budget share: calm below 75%, warning to 90%, danger beyond. */
function usageTone(percent: number): PromptInputTrayTone {
	if (percent >= 90) return 'danger';
	if (percent >= 75) return 'warning';
	return 'info';
}

type UsageNoticeProps = Omit<React.ComponentProps<'div'>, 'children'> & {
	/** Share of the plan budget already spent, 0-100. */
	percent: number;
	/** Overrides the default "You've used N% of your tokens." sentence. */
	message?: React.ReactNode;
	actionLabel?: React.ReactNode;
	actionHref?: string;
	onAction?: () => void;
	onDismiss?: () => void;
};

const linkClass =
	'rounded-sm font-medium text-link underline-offset-2 outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50';

/**
 * Plan-budget line for the header of a `PromptInputTray`:
 *
 * ```tsx
 * <PromptInputTray tone={usageTone(80)} header={<UsageNotice percent={80} onDismiss={dismiss} />}>
 *   <PromptInput … />
 * </PromptInputTray>
 * ```
 */
function UsageNotice({ percent, message, actionLabel = 'View usage', actionHref, onAction, onDismiss, ...props }: UsageNoticeProps) {
	const tone = usageTone(percent);
	const action = actionHref ? (
		<a className={linkClass} href={actionHref} onClick={onAction}>
			{actionLabel}
		</a>
	) : onAction ? (
		<button type="button" className={cn(linkClass, 'cursor-pointer')} onClick={onAction}>
			{actionLabel}
		</button>
	) : null;

	return (
		<PromptInputTrayRow
			data-slot="usage-notice"
			data-tone={tone}
			icon={tone === 'info' ? <Gauge /> : <TriangleAlert />}
			actions={
				onDismiss ? (
					<button
						type="button"
						aria-label="Dismiss"
						onClick={onDismiss}
						className="relative grid size-6 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none before:absolute before:-inset-2 hover:bg-overlay-hover hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 pointer-coarse:before:-inset-2.5"
					>
						<X aria-hidden="true" className="size-3.5" />
					</button>
				) : null
			}
			{...props}
		>
			<p>
				{message ?? (
					<>
						You&apos;ve used <span className="tabular-nums">{Math.round(percent)}%</span> of your tokens.
					</>
				)}
				{action ? <> {action}</> : null}
			</p>
		</PromptInputTrayRow>
	);
}

export { UsageNotice, usageTone };
export type { UsageNoticeProps };

'use client';

import * as React from 'react';

/**
 * Whether an `<img>` failed to load, for a fallback such as initials or an icon.
 *
 * `onError` alone misses an image that failed before React was listening: a
 * server-rendered page can hydrate after the browser has already given up on a
 * dead URL, and that `error` event is never replayed. So the ref also checks the
 * element when it mounts. A finished image with no pixels either failed or is an
 * SVG without an intrinsic size (which reports a natural width of 0 as well), and
 * `decode()` tells the two apart; a browser without it counts the image as failed.
 *
 * `failed` stays set for the life of the component that calls the hook, so key
 * that component by the image address and a new address gets a fresh attempt:
 *
 * ```tsx
 * function Photo({ src, fallback }: { src: string; fallback: React.ReactNode }) {
 *   const { failed, ref, onError } = useImageFailed();
 *   return failed ? fallback : <img ref={ref} src={src} onError={onError} alt="" />;
 * }
 * // <Photo key={url} src={url} fallback={<Initials />} />
 * ```
 */
export function useImageFailed() {
	const [failed, setFailed] = React.useState(false);
	const onError = React.useCallback(() => setFailed(true), []);
	const ref = React.useCallback((image: HTMLImageElement | null) => {
		if (!image || !image.complete || image.naturalWidth > 0) return;
		if (typeof image.decode !== 'function') setFailed(true);
		else image.decode().catch(() => setFailed(true));
	}, []);
	return { failed, ref, onError };
}

'use client';

import { useEffect, useRef, useState } from 'react';

/** Default stream throttle (~15fps) — bounds markdown re-parse cost. */
export const STREAM_THROTTLE_MS = 66;

/**
 * Throttle `text` updates while `streaming` is true; flush immediately when
 * streaming ends so settled content is never delayed.
 */
export function useThrottledText(text: string, streaming: boolean, intervalMs = STREAM_THROTTLE_MS): string {
	const [throttled, setThrottled] = useState(text);
	const latest = useRef(text);
	latest.current = text;
	const lastFlush = useRef(0);
	const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

	useEffect(() => {
		if (!streaming) {
			if (timer.current) {
				clearTimeout(timer.current);
				timer.current = null;
			}
			setThrottled((prev) => (prev === text ? prev : text));
			return;
		}

		const now = Date.now();
		const elapsed = now - lastFlush.current;
		if (elapsed >= intervalMs) {
			lastFlush.current = now;
			setThrottled(text);
		} else if (timer.current == null) {
			timer.current = setTimeout(() => {
				timer.current = null;
				lastFlush.current = Date.now();
				setThrottled(latest.current);
			}, intervalMs - elapsed);
		}
	}, [text, streaming, intervalMs]);

	useEffect(
		() => () => {
			if (timer.current) clearTimeout(timer.current);
		},
		[],
	);

	return throttled;
}
